import type {SpinResult,Win} from './SlotMain';

export const towerSymbol=(name:string)=>'jackpot-rich-night-'+name;
export interface TowerCoin {cell:number;amount:number;}
export type TowerChoice={cell:number;kind:'spins';added:number}|{cell:number;kind:'play'};
export interface TowerPick {cell:number;kind:'spins'|'play';added:number;before:number;after:number;}
export interface TowerStage {board:string[];heldBefore:TowerCoin[];landed:TowerCoin[];heldAfter:TowerCoin[];remainingBefore:number;remainingAfter:number;}
export interface TowerPlayback {triggerBoard:string[];initial:TowerCoin[];baseSpins:number;picks:TowerPick[];awarded:number;stages:TowerStage[];collections:{coin:TowerCoin;win:Win;bankBefore:number;bankAfter:number}[];released:TowerCoin[];}
const integer=(n:number,min=0)=>Number.isSafeInteger(n)&&n>=min;
function coinsCopy(coins:TowerCoin[]){
 if(new Set(coins.map(c=>c.cell)).size!==coins.length||coins.some(c=>!integer(c.cell)||c.cell>=15||!integer(c.amount,1)))throw Error('Invalid tower coins');
 return coins.map(c=>({...c}));
}
/** Explicit free-audit inputs. Observed: 6 base spins, +2/+1 picks until PLAY,
 * previously landed money stays locked, no spin reset on a new coin, and one
 * final collection. Natural trigger odds, full-board/super bonus are pending. */
export function towerSequence(triggerBoard:string[],initial:TowerCoin[],choices:TowerChoice[],turns:TowerCoin[][],bet:number):SpinResult{
 if(!integer(bet,1)||triggerBoard.length!==15||triggerBoard.some(s=>typeof s!=='string'||!s))throw Error('Invalid tower board/bet');
 const starting=coinsCopy(initial),held=coinsCopy(initial),picks:TowerPick[]=[];let remaining=6,playing=false;
 if(starting.some(c=>triggerBoard[c.cell]!==towerSymbol('coin')))throw Error('Tower initial coin missing');
 const used=new Set<number>();
 for(const choice of choices){
  if(playing||!integer(choice.cell)||choice.cell>=12||used.has(choice.cell))throw Error('Invalid tower pick');used.add(choice.cell);
  const before=remaining,added=choice.kind==='spins'?choice.added:0;
  if(choice.kind==='spins'&&(!integer(added,1)||added>100))throw Error('Invalid tower spin addition');
  remaining+=added;if(choice.kind==='play')playing=true;
  picks.push({cell:choice.cell,kind:choice.kind,added,before,after:remaining});
 }
 if(!playing||turns.length!==remaining)throw Error('Tower sequence requires PLAY and all awarded turns');
 const awarded=remaining,stages:TowerStage[]=[];
 for(const turn of turns){
  const landed=coinsCopy(turn),heldBefore=coinsCopy(held);
  if(landed.some(c=>held.some(old=>old.cell===c.cell)))throw Error('Tower cannot replace a held coin');
  const remainingBefore=remaining;remaining--;held.push(...landed);
  const board=Array.from({length:15},(_,cell)=>towerSymbol(held.some(c=>c.cell===cell)?'coin':'void'));
  stages.push({board,heldBefore,landed,heldAfter:coinsCopy(held),remainingBefore,remainingAfter:remaining});
 }
 let bank=0;const collections=[...held].sort((a,b)=>a.cell-b.cell).map(coin=>{
  const bankBefore=bank;bank+=coin.amount;if(!integer(bank))throw Error('Tower payout overflow');
  const win:Win={line:-1,symbol:towerSymbol('coin'),cells:[coin.cell],amount:coin.amount};
  return {coin:{...coin},win,bankBefore,bankAfter:bank};
 });
 return {bet,board:[...stages[stages.length-1].board],payout:bank,wins:collections.map(c=>c.win),towerFeature:{triggerBoard:[...triggerBoard],initial:starting,baseSpins:6,picks,awarded,stages,collections,released:coinsCopy(held)}};
}
