import type {Cascade,SpinResult,Win} from './SlotMain';
import type {VikingCascadeResult} from './VikingCascade';
import {VIKING_SYMBOLS} from './VikingRules';
import {BET_LEVELS} from './BetLevels';

export function vikingOrdinarySymbol(symbol:number):string {
 if(!Number.isInteger(symbol)||symbol<0||symbol>=VIKING_SYMBOLS.length)throw Error('Invalid Viking ordinary symbol');
 return 'viking-runecrafty-'+VIKING_SYMBOLS[symbol];
}
export function vikingSymbol(symbol:number):string {
 if(symbol<9)return vikingOrdinarySymbol(symbol);
 const wild=['wild-thor','wild-odin','wild-freya','wild-heimdall'][symbol-9];
 if(!Number.isInteger(symbol)||!wild)throw Error('Invalid Viking symbol');
 return 'viking-runecrafty-'+wild;
}
/** Converts a fully settled ordinary segment into the shared tumble playback
 * contract. A pending god/charge/Ragnarok segment cannot be paid as a finished
 * spin. Full feature playback will extend this contract before registration. */
export function vikingOrdinaryResult(bet:number,segment:VikingCascadeResult):SpinResult {
 if(!BET_LEVELS.includes(bet)||segment.next!=='settle')throw Error('Viking round is not ready for ordinary settlement');
 if(segment.board.length!==49)throw Error('Invalid Viking final grid');
 const board=segment.board.map(vikingSymbol);
 const cascades:Cascade[]=segment.steps.map((step,index)=>{
  if(step.before.length!==49||step.after.length!==49)throw Error('Invalid Viking playback grid');
  const expected=index+1<segment.steps.length?segment.steps[index+1].before:segment.board;
  if(step.after.some((symbol,cell)=>symbol!==expected[cell]))throw Error('Viking cascade continuity mismatch');
  const wins:Win[]=step.wins.map(win=>{
   if(!Number.isSafeInteger(win.amount)||win.amount<0||Math.abs(win.amount-bet*win.multiple)>1e-8)throw Error('Invalid Viking ordinary payout');
   return {line:-1,symbol:vikingOrdinarySymbol(win.symbol),cells:[...win.cells],amount:win.amount};
  });
  const moved=new Map(step.falls.map(f=>[f.to,f]));
  const spawned=new Map(step.spawned.map(s=>[s.cell,s]));
  const incoming=Array.from({length:7},(_,col)=>step.spawned.filter(s=>s.cell%7===col).length);
  // TumbleAnimator rebuilds its node map from drops: unchanged survivors must
  // be present too, otherwise the next cascade loses those live symbol nodes.
  const drops=step.after.map((symbol,to)=>{
   const row=Math.floor(to/7),col=to%7,fall=moved.get(to),spawn=spawned.get(to);
   const from=spawn?(row-incoming[col])*7+col:fall?.from??to;
   if(spawn&&(from>=0||spawn.symbol!==symbol)||!spawn&&(step.before[from]!==symbol||step.removed.includes(from)))throw Error('Invalid Viking fall mapping');
   return {from,to,symbol:vikingSymbol(symbol)};
  });
  return {vikingProgress:step.progress,vikingCharge:{before:step.chargeBefore,after:step.chargeAfter},board:step.before.map(vikingSymbol),wins,payout:wins.reduce((sum,w)=>sum+w.amount,0),multiplier:1,cellMultipliers:Array(49).fill(0),nextMultipliers:Array(49).fill(0),drops,removedCells:[...step.removed]};
 });
 const wins=cascades.flatMap(stage=>stage.wins),payout=wins.reduce((sum,w)=>sum+w.amount,0);
 if(Math.abs(payout-segment.subtotal)>1e-8)throw Error('Viking settlement omits another segment');
 cascades.push({vikingCharge:{before:segment.charge,after:segment.charge},board:[...board],wins:[],payout:0,multiplier:1,cellMultipliers:Array(49).fill(0),nextMultipliers:Array(49).fill(0),drops:[]});
 return {bet,openingBoard:[...cascades[0].board],board,wins,payout,cascades};
}
