import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {SUBMARINE_ART,SUBMARINE_EFFECT_ART,submarineSymbol as s,submarineVisible,submarineSequence,SubmarineTurn} from './SubmarineFeature';
export class SubmarinePreviewSlot extends SlotMain {
 constructor(private readonly fixture='pack'){super();}
 readonly columns=6;readonly rows=4;readonly mode='lines' as const;readonly paylines:number[][]=[];readonly bets=[...BET_LEVELS];
 get bonusSymbol(){return s('sonar');}get bonusTriggerCount(){return 4;}
 readonly config:SlotConfig={id:'boot-camp-x',title:'심해 순찰대',subtitle:'DEEP SEA PATROL',tag:'전용 어뢰 체험',color:'#233c49',accent:'#9cd3cc',description:'네 칸을 모아 어뢰 발사\n첫 수집 ×2 · 추가 수집 +1\n발사 후 양끝은 일반 심볼\n가운데는 WILD 묶음 공개\n발사 때 전체 배수 +1\n소나마다 추가 2회',symbols:SUBMARINE_ART.map(art=>({id:s(art),name:art.endsWith('_wild')?'WILD':art.replace(/_/g,' '),color:'#9cd3cc',weight:0,payout:0}))};
 artResource(id:string){const name=id.slice('boot-camp-x-'.length);if(![...SUBMARINE_ART,...SUBMARINE_EFFECT_ART].includes(name))throw Error('Unknown submarine art');return 'slot-art-delivered-v1/boot-camp-x/v05/'+name;}
 spin():SpinResult{throw Error('Submarine first draft is free playback only');}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const blank=()=>Array.from({length:24},(_,cell)=>submarineVisible(cell)?s(SUBMARINE_ART[(cell+cell%6)%10]):s('void'));
  if(this.fixture==='no-win')return{bet,board:blank(),wins:[],payout:0};
  const trigger=blank();[19,20,21,22].forEach(cell=>trigger[cell]=s('sonar'));const turns:SubmarineTurn[]=[];
  for(let i=0;i<(this.fixture==='retrigger'?10:8);i++){
   const board=blank(),torpedoes=i===0?[19,20]:i===1?[19,21]:i===2?[22]:[];torpedoes.forEach(cell=>board[cell]=s('torpedo_wild'));
   const cells=[12,13,14];if(i===0||i===3)cells.forEach(cell=>board[cell]=s('captain'));
   if(i===2)board[18]=s('cook');
   const scatters=this.fixture==='retrigger'&&i===4?[19]:[];scatters.forEach(cell=>board[cell]=s('sonar'));
   turns.push({board,torpedoes,regular:i===0||i===3?[{symbol:s('captain'),baseAmount:bet,cells}]:[],launched:i===2?[{symbol:s('cook'),baseAmount:bet*2,cells:[18,19,20,21,22]}]:[],revealSymbol:s('cook'),scatters});
  }
  return submarineSequence(trigger,turns,bet);
 }
}
