import {cloneSlotData} from './SlotMain';
import {SlotMain,SpinResult} from './SlotMain';
import {packRounds,SlotProgress} from './Social2230Rules';
/** Independent purchase sessions. Ordinary wager progress is never consumed or awarded. */
export const additionalBonusRules:Record<string,string>={
 'vault-multiplier-workshop':'금액 금고와 배수 도장 2개를 즉시 개봉합니다.',
 'second-chance-circus':'안전망 WILD를 고정하고 구제 재회전 1회를 진행합니다.',
 'gem-cannon-theatre':'대포 표적 3곳을 공개합니다. 진입 라인 당첨은 제외합니다.',
 'midnight-ballroom':'목표 5/6에서 시작해 과제를 완성하는 회전을 진행합니다.',
 'golden-zodiac-choice':'선택한 황금 별자리의 당첨 회전에 진입합니다.',
 'starlit-cast':'선택 배우가 3등급 공연을 완성합니다.',
 'frost-flame-crossroads':'좌우 양쪽 당첨이 있는 회전을 진행합니다.',
 'ember-pinball':'좌우 발사를 선택하고 핀볼 도착 보상을 받습니다.',
 'red-cloak-expedition':'장비를 선택한 뒤 전투 무료 5회 또는 7회를 진행합니다.',
 'angel-devil-contract':'천사 계약 뒤 즉시 수령 또는 추가 1회 도전을 선택합니다. 추가 회전 뒤 자동 수령합니다.',
 'crystal-seal-breaker':'마지막 봉인을 해제하고 수정 보상을 선택합니다.',
 'golden-city-atlas':'마지막 지도 조각을 수집하고 보물 경로를 선택합니다.',
 'tenth-bell-sheriff':'열 번째 종의 릴 WILD 변환 회전에 진입합니다.',
 'seven-jewel-dig':'보석별 2개를 보유한 별도 상자에서 보석 매치 텀블을 진행합니다.',
};
export const additionalChoiceCount=(id:string)=>id==='red-cloak-expedition'?3:['ember-pinball','angel-devil-contract'].includes(id)?2:['crystal-seal-breaker','golden-city-atlas'].includes(id)?3:0;
export function additionalBonusKey(slot:SlotMain,branch=0){
 if(!additionalBonusRules[slot.config.id])return;
 const selection=(slot as SlotMain&{selection?:number}).selection||0;
 return slot.config.id+':purchase-v1'+(slot.config.id==='starlit-cast'?':actor'+selection:additionalChoiceCount(slot.config.id)?':'+branch:'');
}
type Session=SlotMain&{selection?:number;setProgress?:(value:SlotProgress)=>void;startPinball?:(base:SpinResult,rng:()=>number)=>SpinResult;resolve?:(symbol:any,bet:number,rng?:()=>number)=>SpinResult};
const neutral=(r:SpinResult):SpinResult=>({board:[...r.board],bet:r.bet,payout:0,wins:[],presentation:r.presentation});
const search=(slot:Session,bet:number,rng:()=>number,match:(r:SpinResult)=>boolean)=>{for(let n=0;n<100000;n++){const r=slot.spin(bet,rng);if(match(r))return r;}throw Error('Purchase entry unavailable: '+slot.config.id);};
function finish(r:SpinResult,featureOnly=true):SpinResult{
 r=cloneSlotData(r);
 delete r.progressUpdate;
 if(r.featureChoices){r.featureChoices={...r.featureChoices,results:r.featureChoices.results.map(b=>finish(b,featureOnly))};const first=r.featureChoices.results[r.featureChoices.defaultIndex];return {...first,featureChoices:r.featureChoices};}
 const rounds=r.rounds||[r];for(const q of rounds)delete q.progressUpdate;
 return {...packRounds(rounds,{featureOnly,freeSpinsAwarded:featureOnly?undefined:r.freeSpinsAwarded,featureName:r.featureName,presentation:r.presentation}),bonusTriggerRound:r.bonusTriggerRound||neutral(rounds[0])};
}
function freeOnly(r:SpinResult):SpinResult{
 const rounds=r.rounds!.slice(1);return finish({...packRounds(rounds,{freeSpinsAwarded:r.freeSpinsAwarded,featureName:r.featureName,presentation:r.presentation}),bonusTriggerRound:neutral(r.rounds![0])},false);
}
export function prepareAdditionalBonus(original:SlotMain,bet:number,rng:()=>number):SpinResult|undefined{
 const id=original.config.id;if(!additionalBonusRules[id])return;
 if(!original.bets.includes(bet))throw Error('Invalid purchase bet');
 const slot=new (original.constructor as new()=>Session)(),key=id+':'+bet;
 slot.selection=(original as Session).selection||0;
 const set=(state:number[])=>slot.setProgress!({[key]:state});
 switch(id){
 case 'vault-multiplier-workshop':return finish(search(slot,bet,rng,r=>!!r.vaultFeature&&r.vaultFeature.multipliers.every(n=>n>0)));
 case 'second-chance-circus':return freeOnly(search(slot,bet,rng,r=>!!r.circusFeature?.trigger||!!r.rounds));
 case 'gem-cannon-theatre':{const r=search(slot,bet,rng,r=>!!r.cannonFeature?.shots.length);r.wins=r.cannonFeature!.shots.map(s=>s.win);r.payout=r.wins.reduce((n,w)=>n+w.amount,0);return finish(r);}
 case 'midnight-ballroom':set([Math.floor(rng()*8),5,1]);return finish(search(slot,bet,rng,r=>!!r.ballroomFeature?.success));
 case 'golden-zodiac-choice':return finish(search(slot,bet,rng,r=>!!r.zodiacFeature?.awards.length));
 case 'starlit-cast':{const state=Array(11).fill(0),actor=slot.selection!;state[1+actor]=4+actor;state[6+actor]=2;set(state);return finish(search(slot,bet,rng,r=>!!r.castFeature?.ranked));}
 case 'frost-flame-crossroads':return finish(search(slot,bet,rng,r=>!!r.crossroadsFeature?.left.length&&!!r.crossroadsFeature?.right.length));
 case 'ember-pinball':{
  const symbols=slot.config.symbols,weight=symbols.reduce((n,s)=>n+s.weight,0);
  const board=Array.from({length:15},()=>{let v=rng()*weight;return (symbols.find(s=>(v-=s.weight)<0)||symbols[symbols.length-1]).id;});
  for(const cell of slot.paylines[Math.floor(rng()*slot.paylines.length)])board[cell]=id+'-0';
  const r=slot.startPinball!(slot.evaluate(board,bet),rng),choice=r.featureChoices!;
  const results=choice.results.map(b=>finish({...packRounds(b.rounds!.slice(1),{featureOnly:true,presentation:b.presentation}),bonusTriggerRound:neutral(b.rounds![0])}));
  return {...results[0],featureChoices:{...choice,results}};
 }
 case 'red-cloak-expedition':{
  const results=[0,1,2].map(equipment=>{set([2,1,equipment]);return freeOnly(search(slot,bet,rng,r=>!!r.freeSpinsAwarded));});
  return {...results[0],featureChoices:{title:'구매 전투 장비 선택',labels:['석궁 · 고액 심볼 증가','방패 · WILD 증가','장화 · 무료 2회 추가 / 배당 75%'],results,defaultIndex:0}};
 }
 case 'angel-devil-contract':{
  set([1,1,1,0]);const angel=slot.resolve!(id+'-3',bet),collect=angel.featureChoices!.results[0],hold=angel.featureChoices!.results[1];
  set(hold.progressUpdate!.values);const next=slot.spin(bet,rng),settled=next.featureChoices?.results[0]||next;
  const risk=packRounds([...hold.rounds!,...(settled.rounds||[settled])],{featureOnly:true,presentation:angel.presentation});
  const results=[finish(collect),finish(risk)];return {...results[0],featureChoices:{title:'천사 계약 · 수령 또는 추가 도전',labels:['지금 수령','추가 1회 도전 · 이후 자동 수령'],results,defaultIndex:0,noBonusEntry:true}};
 }
 case 'crystal-seal-breaker':set([1<<7]);return finish(search(slot,bet,rng,r=>!!r.featureChoices));
 case 'golden-city-atlas':set([4,4,4,3,2,3]);return finish(search(slot,bet,rng,r=>!!r.featureChoices));
 case 'tenth-bell-sheriff':set([9]);return finish(search(slot,bet,rng,r=>!!r.bellFeature?.columns.length));
 case 'seven-jewel-dig':set(Array(7).fill(2));return finish(search(slot,bet,rng,r=>!!r.jewelFeature?.stages.some(s=>s.gems.some(g=>g.matched))));
 }
 throw Error('Missing purchase profile: '+id);
}
