export interface AvatarPreset {id:string;name:string;skin:'black'|'white'|'yellow';gender:'male'|'female';tone:string;hair:string;style:number;width:number;height:number;face:number;accent:string;}
const names=['모모','루키','리오','소라','테오','나나','코코','루나','유키','로이','미오','토리','노아','보리','레오','라라','제이','로하','미카','아리','루이','하루','니코','세나','로빈','이든','레미','도리','네오','마루','피오','다나','유노','로미','누리','로키','시온','보노','리나','카이'];
const tones=['#80513f','#f2d5c0','#d3a073','#ad7050','#eac39b','#684333'];
const hair=['#302433','#b36e45','#e3c378','#684b78','#3b465b'];
// A stable shuffled cast: presentation never groups people by skin or gender.
export const avatarPresets:AvatarPreset[]=names.map((name,i)=>({
 id:'pocket-'+String(i+1).padStart(2,'0'),name,skin:(['black','white','yellow','black','yellow','black'] as const)[i%6],
 gender:i%4===0||i%4===3?'female':'male',tone:tones[i%6],hair:hair[Math.floor(i/8)],style:(i*3+Math.floor(i/8))%8,
 width:[.94,.88,1.14,1.06,.98][i%5],height:[1.08,1.16,1,1.12][(i*3+Math.floor(i/5))%4],face:(i*7)%5,
 accent:['#8bd7d0','#f0b280','#baa1ec','#e7a0c2','#b6d77d'][i%5]
}));
export const avatarPreset=(id?:string)=>avatarPresets.find(p=>p.id===id);
