import {native,sys} from 'cc';
import {completedReviewSpin,completedSlotVisit,finishedReviewAttempt,parseReviewPromptState,ReviewPromptState,shouldRequestReview} from './ReviewPromptPolicy';

const STORAGE_KEY='pocket-in-app-review-v1';
type Storage={getItem(key:string):string|null;setItem(key:string,value:string):void};

/** Requests the store-owned rating card only after meaningful play. The store
 * decides whether the card is actually shown and owns the entire review UI. */
export class InAppReview{
 private state:ReviewPromptState;
 private pending=false;
 constructor(private storage:Storage){this.state=this.read();}
 private read(){try{return parseReviewPromptState(this.storage.getItem(STORAGE_KEY));}catch{return parseReviewPromptState(null);}}
 private save(next:ReviewPromptState){this.state=next;try{this.storage.setItem(STORAGE_KEY,JSON.stringify(next));}catch{/* Store quota still protects users if persistence is unavailable. */}}
 recordCompletedSpin(){this.save(completedReviewSpin(this.state));}
 recordSlotExit(){this.save(completedSlotVisit(this.state));}
 get supported(){return sys.isNative&&(sys.os===sys.OS.ANDROID||sys.os===sys.OS.IOS);}
 async requestIfEligible(now=Date.now()){
  if(!this.supported||this.pending||!shouldRequestReview(this.state,now))return false;
  this.pending=true;let launched=false;
  try{
   if(sys.os===sys.OS.ANDROID)launched=await this.requestAndroid();
   else launched=native.reflection.callStaticMethod('PocketReview','request:','rating')==='requested';
  }catch{/* A store or bridge failure must not interrupt the lobby. */}
  finally{this.save(finishedReviewAttempt(this.state,now,launched));this.pending=false;}
  return launched;
 }
 private async requestAndroid(){
  const id=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
  const call=(method:string)=>native.reflection.callStaticMethod('com/cocos/game/PocketReview',method,'(Ljava/lang/String;)Ljava/lang/String;',id) as string;
  if(call('request')!=='loading')return false;
  const started=Date.now();
  while(Date.now()-started<10*60*1000){
   await new Promise(resolve=>setTimeout(resolve,250));
   const status=call('poll');
   if(status==='completed')return true;
   if(status==='failed')return false;
  }
  try{call('cancel');}catch{}
  return false;
 }
}
