import type {Win} from './SlotMain';

export type GladiatorMode='arena'|'beast';
export interface GladiatorState {
 mode:GladiatorMode;lives:number;played:number;reels:number[];unlocked:boolean[];
}
export interface GladiatorDuel {reel:number;left:number;right:number;winner:'left'|'right'}
export interface GladiatorCoin {cell:number;factor:number;epic:boolean}
export type GladiatorEvent=
 |{kind:'duel';duel:GladiatorDuel;before:GladiatorState;after:GladiatorState}
 |{kind:'unlock';before:GladiatorState;after:GladiatorState}
 |{kind:'coin';coin:GladiatorCoin;targets:number[];before:GladiatorState;after:GladiatorState};
export interface GladiatorPlayback {
 payoutMode?:'bank'|'lines';
 collection?:{values:number[];rawMultiplier:number;paidMultiplier:number;award:Win;capReached:boolean};
 before:GladiatorState;afterConsume:GladiatorState;after:GladiatorState;
 events:GladiatorEvent[];expanded:number[];wins:Win[];added:number;
}
export const gladiatorSymbol=(name:string)=>'gladiator-lore-'+name;
export const gladiatorCopy=(state:GladiatorState):GladiatorState=>({...state,reels:[...state.reels],unlocked:[...state.unlocked]});
export function gladiatorStart(mode:GladiatorMode):GladiatorState{
 return {mode,lives:3,played:0,reels:[0,0,0,0,0],unlocked:[false,false,mode==='arena',false,false]};
}
/** First-draft transition contract. Reel outcomes and pre-multiplier line wins
 * come from the caller. No natural reel distribution or unverified paytable is
 * invented here. Duel replacement and same-turn unlock order remain draft policy. */
export function gladiatorResolve(state:GladiatorState,duels:GladiatorDuel[],coins:GladiatorCoin[],baseWins:Win[]):GladiatorPlayback{
 if(!Number.isInteger(state.lives)||state.lives<1||state.lives>3)throw Error('Gladiator bonus is not active');
 const before=gladiatorCopy(state),afterConsume=gladiatorCopy(state);afterConsume.lives--;afterConsume.played++;
 let current=gladiatorCopy(afterConsume);const events:GladiatorEvent[]=[],expanded:number[]=[];
 for(const duel of duels){
  if(!Number.isInteger(duel.reel)||duel.reel<0||duel.reel>4||expanded.includes(duel.reel))throw Error('Invalid or duplicate duel reel');
  if(![duel.left,duel.right].every(n=>Number.isSafeInteger(n)&&n>=1)||!['left','right'].includes(duel.winner))throw Error('Invalid duel outcome');
  if(current.mode==='beast'&&duel.reel===2&&!current.unlocked[2])throw Error('Beast centre is still locked');
  const previous=gladiatorCopy(current);current.reels[duel.reel]=duel[duel.winner];current.unlocked[duel.reel]=true;
  expanded.push(duel.reel);events.push({kind:'duel',duel:{...duel},before:previous,after:gladiatorCopy(current)});
  if(current.mode==='beast'&&!current.unlocked[2]&&[0,1,3,4].every(reel=>current.unlocked[reel])){
   const locked=gladiatorCopy(current);current.unlocked[2]=true;events.push({kind:'unlock',before:locked,after:gladiatorCopy(current)});
  }
 }
 const payoutState=gladiatorCopy(current),seenCoins=new Set<number>();
 for(const coin of coins){
  if(current.mode!=='arena')throw Error('Arena coins cannot appear in Beast mode');
  if(!Number.isInteger(coin.cell)||coin.cell<0||coin.cell>=20||seenCoins.has(coin.cell)||!Number.isSafeInteger(coin.factor)||coin.factor<2)throw Error('Invalid coin');
  seenCoins.add(coin.cell);const previous=gladiatorCopy(current);
  const targets=(coin.epic?[0,1,2,3,4]:[coin.cell%5]).filter(reel=>current.reels[reel]>0);
  targets.forEach(reel=>{current.reels[reel]*=coin.factor;if(!Number.isSafeInteger(current.reels[reel]))throw Error('Gladiator multiplier overflow');});
  events.push({kind:'coin',coin:{...coin},targets,before:previous,after:gladiatorCopy(current)});
 }
 // Multipliers apply only to duel WILD reels participating in the current line.
 // Stored counters are never paid again just because the next spin began.
 const wins=baseWins.map(win=>{
  if(!Number.isFinite(win.amount)||win.amount<0||win.cells.some(cell=>!Number.isInteger(cell)||cell<0||cell>=20))throw Error('Invalid Gladiator line win');
  const hitReels=expanded.filter(reel=>win.cells.some(cell=>cell%5===reel));
  const centre=payoutState.mode==='beast'&&expanded.includes(2)?payoutState.reels[2]:1;
  const multiplier=hitReels.reduce((sum,reel)=>sum+payoutState.reels[reel]*(payoutState.mode==='beast'&&reel!==2?centre:1),0)||1;
  const amount=win.amount*multiplier;if(!Number.isSafeInteger(amount))throw Error('Gladiator award must be safe integer coins');
  return {...win,cells:[...win.cells],amount,multiplier};
 });
 const added=duels.length?3-current.lives:0;if(duels.length)current.lives=3;
 return {before,afterConsume,after:gladiatorCopy(current),events,expanded,wins,added};
}
