import type {SpinResult,SlotMain} from '../slots/SlotMain';
import type {QuestEvidence} from './QuestPolicy';
/** Evidence accompanies the immutable round receipt; never derives from UI animation. */
export function questEvidence(result:SpinResult,slot:SlotMain):QuestEvidence{
 const rounds=result.rounds||[result];
 const freeSpins=rounds.filter((r,i)=>i>0&&typeof r.freeSpinsRemaining==='number'&&(!r.moonFeature||r.moonFeature.mode==='free')).length;
 const naturalBonus=!!(result.freeSpinsAwarded||result.rounds&&result.rounds.length>1&&!result.featureOnly);
 const wilds=new Set(slot.config.symbols.filter(s=>/wild/i.test(s.id)||/와일드/.test(s.name)).map(s=>s.id));
 const winning=(board:string[],wins:SpinResult['wins'])=>wins.some(w=>w.amount>0&&w.cells.some(cell=>wilds.has(board[cell])));
 const winningWild=rounds.some(r=>winning(r.board,r.wins)||(r.cascades||[]).some(s=>winning(s.board,s.wins)));
 return{version:1,naturalBonus,freeSpins:naturalBonus?Math.min(1000,freeSpins):0,winningWild};
}
