/** Road Rage manufacturer help (2024), geometry and trigger rules only.
 * Not a payout engine. Multiple-car resolution order still needs live review. */
export type RoadColor='red'|'green'|'yellow';
export type RoadMode='morning'|'highway'|'city';
export interface RoadCar {cell:number;color:RoadColor;multiplier:number;sticky:boolean;}
export interface RoadTravel {from:number;to:number;path:number[];stop:'edge'|'blocked'|'collision'|'stationary';}
export interface RoadCollision {green:number;red:number;cell:number;multiplier:number;sticky:boolean;}
export interface RoadPlan {travel:RoadTravel[];collisions:RoadCollision[];}
export const ROAD_MODES={morning:{rows:3,spins:6,stickyColors:1},highway:{rows:4,spins:8,stickyColors:2},city:{rows:5,spins:10,stickyColors:3}} as const;
export function roadTrigger(scatters:number):{respin:boolean;mode?:RoadMode}{
 if(!Number.isInteger(scatters)||scatters<0||scatters>5)throw Error('Invalid Road scatter count');
 return scatters<3?{respin:scatters===2}:{respin:false,mode:scatters===3?'morning':scatters===4?'highway':'city'};
}
/** Upgrade is queued; callers must exhaust the current mode before entering it. */
export function roadPendingUpgrade(mode:RoadMode,scatters:number):RoadMode|undefined{
 if(!Number.isInteger(scatters)||scatters<0||scatters>5)throw Error('Invalid Road scatter count');
 if(!scatters||mode==='city')return undefined;
 return mode==='morning'&&scatters===1?'highway':'city';
}
/** Plan one simultaneous horizontal drive from a fixed board snapshot.
 * Blockers include scatter and mystery cells; cars are blockers themselves.
 * Every intermediate cell is retained for continuous animation, not teleports.
 * Size expansion and repeat phases belong to the eventual feature engine. */
export function roadTravelPlan(rows:number,cars:readonly RoadCar[],blockers:readonly number[]):RoadPlan{
 if(![3,4,5].includes(rows))throw Error('Invalid Road rows');
 const valid=(cell:number)=>Number.isInteger(cell)&&cell>=0&&cell<rows*5;
 if(blockers.some(cell=>!valid(cell))||cars.some(car=>!valid(car.cell)||!['red','green','yellow'].includes(car.color)||!Number.isInteger(car.multiplier)||car.multiplier<0))throw Error('Invalid Road board');
 if(new Set(cars.map(car=>car.cell)).size!==cars.length||cars.some(car=>blockers.includes(car.cell)))throw Error('Overlapping Road cells');
 const occupied=new Set([...blockers,...cars.map(car=>car.cell)]),collisions:RoadCollision[]=[],paired=new Map<number,RoadCollision>();
 for(const green of cars){
  if(green.color!=='green')continue;
  const row=Math.floor(green.cell/5);
  for(let cell=green.cell+1;cell<(row+1)*5;cell++){
   if(!occupied.has(cell))continue;
   const red=cars.find(car=>car.cell===cell&&car.color==='red'),gap=cell-green.cell-1;
   if(red&&gap>0&&gap%2===1){const collision={green:green.cell,red:red.cell,cell:(green.cell+red.cell)/2,multiplier:green.multiplier+red.multiplier,sticky:green.sticky||red.sticky};collisions.push(collision);paired.set(green.cell,collision);paired.set(red.cell,collision);}
   break;
  }
 }
 const travel=cars.map((car):RoadTravel=>{
  const path=[car.cell],direction=car.color==='red'?-1:car.color==='green'?1:0;
  if(!direction)return{from:car.cell,to:car.cell,path,stop:'stationary'};
  const collision=paired.get(car.cell),row=Math.floor(car.cell/5);
  if(collision){for(let cell=car.cell+direction;cell!==collision.cell+direction;cell+=direction)path.push(cell);return{from:car.cell,to:collision.cell,path,stop:'collision'};}
  for(let cell=car.cell+direction;cell>=row*5&&cell<(row+1)*5;cell+=direction){
   if(occupied.has(cell))return{from:car.cell,to:path[path.length-1],path,stop:'blocked'};
   path.push(cell);
  }
  return{from:car.cell,to:path[path.length-1],path,stop:'edge'};
 });
 return{travel,collisions};
}
