import type {SpinResult,Cascade} from './SlotMain';
import {vikingChargeRound} from './VikingChargeRound';
import {vikingOrdinaryResult,vikingSymbol} from './VikingResult';
import {vikingDestructionStage} from './VikingEffectResult';
import {vikingCapAwards} from './VikingSettlement';
/** Pay only a completed base + charge-effect chain, never a Ragnarok boundary. */
export function vikingChargeResult(bet:number,source:ReturnType<typeof vikingChargeRound>):SpinResult {
 if(source.next!=='settle'||source.events[source.events.length-1]?.kind!=='cascades')throw Error('Viking charge round is not settled');
 const cascades:Cascade[]=[];let previous:number[]|undefined,subtotal=0,effects=0;
 for(const [index,event] of source.events.entries()){
  if(event.kind==='destruction'){
   if(++effects>1||!previous||event.effect.before.some((s,c)=>s!==previous![c]))throw Error('Invalid Viking charge effect order');
   cascades.push(vikingDestructionStage(event.effect));previous=[...event.effect.after];
  }else{
   const segment=event.segment,opening=segment.steps[0]?.before||segment.board;
   if(previous&&opening.some((s,c)=>s!==previous![c]))throw Error('Discontinuous Viking charge round');
   const sum=segment.steps.reduce((n,step)=>n+step.wins.reduce((s,w)=>s+w.amount,0),0);subtotal+=sum;
   if(segment.subtotal!==subtotal)throw Error('Invalid Viking charge accumulated award');
   // The coordinator has resolved the first segment's pending effect. Convert
   // its awards without pretending that segment could settle independently.
   const part=vikingOrdinaryResult(bet,{...segment,next:'settle',subtotal:sum});
   cascades.push(...(index===source.events.length-1?part.cascades!:part.cascades!.slice(0,-1)));
   previous=[...segment.board];
  }
 }
 if(!previous||source.board.some((s,c)=>s!==previous![c])||subtotal!==source.subtotal||!!effects!==source.effectPlayed)throw Error('Incomplete Viking charge settlement');
 const limited=vikingCapAwards(cascades,bet,1),wins=cascades.flatMap(stage=>stage.wins);
 return {bet,board:source.board.map(vikingSymbol),openingBoard:[...cascades[0].board],wins,payout:limited.payout,cascades};
}
