   const names:string[]=[];let at=0,pattern='^';for(const match of value.matchAll(/\{(\w+)\}/g)){pattern+=escapeRegex(value.slice(at,match.index))+'(.+?)';names.push(match[1]);at=match.index!+match[0].length;}pattern+=escapeRegex(value.slice(at))+'$';return {key,pattern:new RegExp(pattern),names,weight:value.replace(/\{\w+\}/g,'').length};
